/* Feeds to connect in production (from the public-data list: global ones and those for this country; feeds.json provides scope) */
function feedsSection(box, sc, no) {
  const feeds = M.feeds(); const cj = COUNTRY_JA[sc.country] || '';
  const isCountry = (f) => f.scope === sc.country;
  const isGlobal = (f) => f.scope === 'global';
  const shown = feeds.filter(isGlobal).slice(0, 10).concat(feeds.filter(isCountry).slice(0, 10));
  const feedRow = (f) => `<div class="feed"><div><b>${esc(f.name)} <span class="muted" style="font-weight:400">· ${esc(f.provider || '')}</span></b><span>${esc(f.use_in_app_ja || f.covers_ja || '')}</span>${f.api ? `<span class="mono" style="font-size:10.5px;color:var(--muted);word-break:break-all">${esc(f.api)}</span>` : ''}</div><div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap"><span class="tag neutral">${esc(f.format || '')}</span>${f.url ? `<a class="cite" href="${esc(f.url)}" target="_blank" rel="noopener">${ic('link')}Official</a>` : ''}<span class="tag ${f.confirmed_by === 'third_party' ? 'neutral' : 'warn'}" title="${f.confirmed_by === 'third_party' ? 'URL confirmed via client implementations etc. (official page itself not retrieved)' : 'Not verified'}">${f.confirmed_by === 'third_party' ? 'URL confirmed' : 'To verify'}</span><span class="tag warn">Not connected</span></div></div>`;
  box.innerHTML = `<details class="more"><summary>${ic('chev')}<span class="no" style="font-family:var(--f-mono);font-size:11px;color:var(--accent);font-weight:600;margin-right:8px">${no}</span>What this would connect to in production (${shown.length} public feeds · not connected yet)</summary><div class="body"><p style="margin:0 0 10px;color:var(--fg2);font-size:13px">Public feeds matching the panels on this screen (global ones and those for ${esc(cj)}). Everything shown now is demo data. API URLs were checked against client implementations on GitHub and similar; terms of use and rate limits must be verified on each official page.</p><div class="card feeds">${shown.map(feedRow).join('') || '<div class="empty">No feeds listed</div>'}</div></div></details>`;
}
/* Overview for the watch phase (no impacts yet). The first forcing is the headline reading; the others are further KPIs */
function watchOverview(box, sc, r, t) {
  const fs = sc.forcing || []; const feed = liveFeed(sc).filter((x) => x.t <= t); const tm = scenTime(sc, t);
  const lvl = (f) => { const v = forcingAt(f, t); const c = (f.thresholds || []).filter((th) => v >= th.v); return c.length ? c[c.length - 1] : null; };
  const head = fs[0] || null; const rest = fs.slice(1); const hasGates = fs.some((f) => f.kind === 'river' || f.kind === 'level');
  const worst = fs.map((f) => ({ f, l: lvl(f) })).filter((x) => x.l).sort((a, b) => b.f.thresholds.indexOf(b.l) - a.f.thresholds.indexOf(a.l))[0];
  const sites = (sc.supply_sites || []).map((id) => M.sites().find((s) => s.id === id)).filter(Boolean);
  const acts = (sc.actions || []); const nextA = acts.filter((a) => a.t <= t).slice(-1)[0] || acts[0];
  const dmg = feed.filter((x) => x.cat === 'damage');
  box.innerHTML = `<div class="answer"><span class="k">Situation</span><ul><li><b>As of ${esc(tm.full)}:</b> the warning remains in force. Impact reports: ${dmg.length} (all minor). ${worst ? `${esc(worst.f.name_ja.split(' (')[0])} is at "${esc(worst.l.ja)}".` : hasGates ? 'River gauges and water gates are all below threshold.' : 'All monitored readings are below threshold.'}</li><li><b>Decision:</b> ${esc(nextA ? nextA.ja : 'Continue normal operations and re-check before the morning commute')}.</li></ul></div>
    <div class="kpis">${[
      { v: 'In force', u: '', l: sc.hazard_ja || 'Warning', c: 'warn', s: 'issued by ' + (sc.agency_ja || 'national hydromet service') },
      head ? { v: fmt(forcingAt(head, t), fDec(head)), u: head.unit, l: head.name_ja.split(' (')[0], c: lvl(head) ? 'crit' : 'warn', s: lvl(head) ? lvl(head).ja : (head.thresholds || []).length ? `below ${fmtF(head.thresholds[0].v, head)}` : 'no threshold set' } : null,
      ...rest.map((f) => ({ v: fmt(forcingAt(f, t), fDec(f)), u: f.unit, l: f.name_ja.split(' (')[0], c: lvl(f) ? (f.thresholds.indexOf(lvl(f)) >= 1 ? 'crit' : 'warn') : 'ok', s: lvl(f) ? lvl(f).ja : 'below threshold' })),
      { v: fmt(dmg.length), u: '', l: 'Impact reports', c: dmg.length ? 'warn' : 'ok', s: dmg.length ? 'all minor so far' : 'none reported' },
      { v: `${sites.length}`, u: 'sites', l: 'Sites under watch', c: 'ok', s: sites.map((s) => s.label + ' operating normally').join(' · ') || '—' },
    ].filter(Boolean).map(kpiTile).join('')}</div>
    <div class="grid map"><div class="card flush"><div class="map-box tall"><svg id="lsMap" role="img" aria-label="Warning area"></svg><div class="legend" id="lsLegend"><span class="t">Legend</span><span><i style="background:var(--b2)"></i>Area under warning</span><span><i style="background:var(--sel);border-radius:50%"></i>Our sites</span></div><div class="attr">Natural Earth · warning area is scenario data</div></div></div>
      <div class="stack"><div class="card"><div class="card-h"><h2>Thresholds being monitored</h2><span class="r">${asmTag('Thresholds to verify')}</span></div><div class="gauges" style="grid-template-columns:1fr">${fs.map((f) => gaugeCard(f, t)).join('')}</div></div>
      <div class="card admin-only"><div class="card-h"><h2>Response and decisions (crisis team)</h2><span class="r"><span class="tag neutral">Managers</span></span></div><ul style="margin:0;padding-left:18px;font-size:13px">${acts.map((a) => `<li${a.t > t ? ' class="muted"' : ''}><b>${esc(a.ja)}</b>${a.why ? `<span class="muted"> — ${esc(a.why)}</span>` : ''}${a.t > t ? ` <span class="tag neutral">planned ${esc(fmtHours(a.t))}</span>` : ''}</li>`).join('')}</ul></div>
      <div class="card"><div class="card-h"><h2>Timeline</h2></div><div class="timeline">${r.log.slice().reverse().map(tlRow).join('')}${r.upcoming.map(tlFut).join('')}</div></div></div></div>`;
  renderRegionMap($('#lsMap', box), { bbox: sc.bbox, labels: true, level: (f) => ((sc.map_adm1 || []).includes(f.properties.id) ? 'b2' : ''), tip: (f) => `<b>${esc(f.properties.n)}</b><div class="r"><span>${(sc.map_adm1 || []).includes(f.properties.id) ? 'Under warning' : 'Not under warning'}</span></div>`, sites: sites.map((s) => ({ id: s.id, lon: s.lon, lat: s.lat, label: s.label, name: `${s.name_ja}: operating normally · under watch`, status: 'ok' })), onSite: (id) => { const s = sites.find((x) => x.id === id); toast(s ? `${s.name_ja}: operating normally · under watch` : id); } });
}

/* ---------- Tab 2: Hazard drivers ---------- */
function panelForcing(box, sc, t) {
  const fs = sc.forcing || [];
  box.innerHTML = `<div class="sec-h"><h2>Hazard drivers</h2><span class="r"><span class="tag neutral">${fs.length} series</span>${asmTag('Trajectories assumed')}</span><p>Trajectories and thresholds for rainfall, river levels, temperature, wind, discharge and seismic activity. Solid line = to date, dotted = projection. Threshold crossings are logged automatically in the incident log. In production these come from each country's hydromet and emergency-agency feeds (see "What this would connect to in production").</p></div>
    <div class="gauges">${fs.map((f) => gaugeCard(f, t)).join('')}</div>
    <div class="grid c2">${fs.map((f, i) => `<div class="card"><div class="card-h"><h2>${esc(f.name_ja)}</h2><span class="r">${f.src ? (/assum/i.test(f.src) ? `<span class="tag asm" title="${esc(f.src)}">Assumed</span>` : `<span class="tag src" title="${esc(f.src)}">${esc(f.src.length > 28 ? f.src.slice(0, 28) + '…' : f.src)}</span>`) : ''}</span></div><div class="chart" id="fc-${i}"></div>${(f.thresholds || []).length ? `<div class="chart-cap">${f.thresholds.map((th) => `<span><i class="ln" style="background:var(--warn)"></i>${esc(th.ja)}: ${fmtF(th.v, f)}</span>`).join('')}</div>` : ''}</div>`).join('')}</div>`;
  fs.forEach((f, i) => { const el = $(`#fc-${i}`, box); if (f.kind === 'quake') stemChart(el, { events: f.events || [], now: t, yLabel: f.name_ja, thresholds: f.thresholds || [] }); else lineChart(el, { now: t, height: 190, yLabel: f.name_ja, yMin: f.kind === 'river' || f.kind === 'level' || f.kind === 'tide' || f.kind === 'temp' ? null : 0, thresholds: f.thresholds || [], series: [{ name: f.unit, color: fColor(f.kind), values: forcingSeries(f) }], yFmt: (v) => fmt(v, fDec(f) ? 1 : 0) }); });
}

/* ---------- Tab 3: Incident log ---------- */
function panelIncidents(box, sc, r, t) {
  const all = liveFeed(sc); const past = all.filter((x) => x.t <= t); const cat = Live.st.incCat || 'all';
  const lastT = Live.st.seen[sc.id]; Live.st.seen[sc.id] = t;
  const shown = past.filter((x) => cat === 'all' || x.cat === cat).slice().reverse().slice(0, 80);
  const byType = countBy(past, 'type'), byDist = countBy(past.filter((x) => x.cat === 'damage'), 'district');
  const dName = (id) => { const d = (sc.districts || []).find((x) => x.id === id); return d ? d.name_ja.split(' (')[0] : id; };
  const fut = all.filter((x) => x.t > t && (x.type === 'forcing' || x.type === 'ops' || x.type === 'shelter')).slice(0, 6);
  box.innerHTML = `<div class="grid map">
    <div class="card"><div class="card-h"><h2>Incident feed</h2><span class="r"><span class="tag crit">${past.filter((x) => x.t > t - 6).length} in the last 6 h</span><span class="tag neutral">${past.length} total</span></span><div class="pills" style="flex-basis:100%">${INC_CATS.map(([k, l]) => `<button class="pill" data-cat="${k}" aria-pressed="${cat === k}">${esc(l)}${k !== 'all' ? ` ${past.filter((x) => x.cat === k).length}` : ''}</button>`).join('')}</div></div><div class="inc-list">${shown.map((x) => incRow(sc, x, lastT != null && x.t > lastT && x.t <= t)).join('') || '<div class="empty">No reports in this category yet</div>'}</div>${past.length > 80 ? `<div class="muted" style="font-size:12px;margin-top:8px">Showing the latest 80</div>` : ''}</div>
    <div class="stack">
      <div class="card"><div class="card-h"><h2>Reports by type</h2></div>${miniBars(Object.entries(byType).sort((a, b) => b[1] - a[1]).map(([k, v]) => ({ label: (INC[k] || [k])[0], value: v, color: INC_CATS[1][0] && ['forcing', 'quake'].includes(k) ? 'var(--c3)' : ['ops', 'req', 'site', 'logi'].includes(k) ? 'var(--c1)' : 'var(--crit)' })))}</div>
      <div class="card"><div class="card-h"><h2>Impact reports by district</h2></div>${Object.keys(byDist).length ? miniBars(Object.entries(byDist).sort((a, b) => b[1] - a[1]).map(([k, v]) => ({ label: dName(k), value: v, color: 'var(--warn)' }))) : '<div class="empty">No reports with an identified district</div>'}</div>
      <div class="card"><div class="card-h"><h2>Outlook</h2><span class="r">${asmTag('Model / schedule')}</span></div><div class="timeline">${fut.map((x) => `<div class="tl future"><span class="t">${esc(fmtHours(x.t))}<b>${esc(scenTime(sc, x.t).time)}</b></span><span class="m"><b>${esc(x.ja)}</b><span>${esc(x.where_ja || '')}</span></span></div>`).join('') || '<div class="empty">Nothing scheduled or projected</div>'}</div></div>
    </div></div>`;
}

/* ---------- Tab 4: Sites and supply chain ---------- */
function onsetHour(sc, did, th = 0.25) { /* First hour at which the district impact exceeds th (hourly steps, cached) */
  sc._onset = sc._onset || {}; const key = did + ':' + th; if (sc._onset[key] !== undefined) return sc._onset[key];
  let out = null; for (let t = 0; t <= 168; t++) { const d = sim(sc, t).districts.find((x) => x.id === did); if (d && d.I > th) { out = t; break; } } sc._onset[key] = out; return out;
}
function panelSites(box, sc, r, t) {
  const g = GD(); const watch = sc.status === 'watch'; const regSites = M.sites(); const siteIds = sc.supply_sites || [];
  const nodeAttr = (s) => `data-node='${JSON.stringify({ type: 'site', region: s.region, site: s.id })}'`;
  const siteRows = r.sites.length ? r.sites.map((s) => { const reg = regSites.find((x) => x.id === s.id); const d = r.districts.find((x) => x.id === s.district); return `<tr><td><b>${esc(s.label)} ${esc(s.name_ja)}</b><span class="sub">${esc(s.district_ja || '')}${d ? ' · district impact: ' + sevJa(d.I) : ''}</span></td><td><span class="tag ${s.status}">${esc(s.op)}</span></td><td class="n">${fmt(s.confirmed)}/${fmt(s.staff)}<span class="sub">${fmtPct(s.resp)}</span></td><td style="font-size:12px;color:var(--fg2)">${esc(s.I > 0.6 ? s.need_crit_ja || 'Evacuate personnel, switch to alternate site' : s.I > 0.25 ? s.need_warn_ja || 'Resupply fuel and drinking water' : '—')}</td><td>${reg ? `<a href="#risk" class="cite" ${nodeAttr(reg)}>${ic('link')}Preparedness score ${siteScore(reg).total}</a>` : '<span class="tag neutral">Scenario-only entry</span>'}</td></tr>`; }).join('') : siteIds.map((id) => regSites.find((s) => s.id === id)).filter(Boolean).map((s) => `<tr><td><b>${esc(s.label)} ${esc(s.name_ja)}</b><span class="sub">${esc(s.short_ja)}</span></td><td><span class="tag ok">Operating normally</span></td><td class="n">—<span class="sub">Safety check not triggered</span></td><td style="font-size:12px;color:var(--fg2)">Communicate remote-work criteria</td><td><a href="#risk" class="cite" ${nodeAttr(s)}>${ic('link')}Preparedness score ${siteScore(s).total}</a></td></tr>`).join('');
  /* Partners and logistics */
  const chain = siteIds.flatMap((sid) => (g.supply[sid] || []).map((x) => Object.assign({ site: sid }, x)));
  const rows = chain.map((x) => { const d = x.district ? r.districts.find((dd) => dd.id === x.district) : null; const I = d ? d.I : 0; const st = d ? (I > 0.6 ? 'crit' : I > 0.25 ? 'warn' : I > 0.05 ? 'ok' : 'none') : 'none'; const onset = d ? onsetHour(sc, x.district) : null; const inv = x.inventory_days != null ? (onset != null && t >= onset ? Math.max(0, x.inventory_days - (t - onset) / 24) : x.inventory_days) : null; return Object.assign({}, x, { d, I, st, onset, inv }); });
  const kindJa = { supplier: 'Supplier', customer: 'Customer', logistics: 'Logistics', utility: 'Utility' };
  const stJa = { crit: 'Expected to stop', warn: 'Degraded / delayed', ok: 'Partly affected', none: watch ? 'Under watch' : 'No impact' };
  const shareBy = (kind) => { const o = {}; rows.filter((x) => x.kind === kind && (x.st === 'crit' || x.st === 'warn')).forEach((x) => { o[x.site] = (o[x.site] || 0) + (x.share || 0); }); const e = Object.entries(o).sort((a, b) => b[1] - a[1])[0]; return e ? { v: Math.min(1, e[1]), site: regSites.find((s) => s.id === e[0]) } : { v: 0, site: null }; };
  const sup = shareBy('supplier'), cus = shareBy('customer'); const supShare = sup.v, cusShare = cus.v;
  const lowInv = rows.filter((x) => x.inv != null && x.inv < 3 && x.st !== 'none').length; const single = rows.filter((x) => x.single && (x.st === 'crit' || x.st === 'warn')).length;
  const kpis = [
    { v: `${r.sites.filter((s) => s.status === 'ok').length}/${r.sites.length || siteIds.length}`, u: 'sites', l: 'Sites operating normally', c: r.sites.length && r.sites.filter((s) => s.status === 'ok').length < r.sites.length ? 'warn' : 'ok', s: r.sites.length ? `${r.kpi.sitesDown} down · ${r.sites.filter((s) => s.status === 'warn').length} degraded` : 'Watch phase · monitoring' },
    { v: r.sites.length ? fmtPct(r.kpi.confirmed / Math.max(1, r.kpi.staff)) : '—', u: '', l: `Safety confirmation rate (${STAFF_JA()})`, c: r.sites.length ? (r.kpi.confirmed / Math.max(1, r.kpi.staff) < 0.9 ? 'warn' : 'ok') : '', s: r.sites.length ? `${fmt(r.kpi.staff - r.kpi.confirmed)} unconfirmed` : 'Not triggered' },
    { v: fmtPct(supShare), u: '', l: 'Procurement share affected', c: supShare > 0.3 ? 'crit' : supShare > 0 ? 'warn' : 'ok', s: sup.site ? `${sup.site.label} ${sup.site.short_ja}: combined share of suppliers degraded or expected to stop (worst site)` : 'No suppliers degraded or expected to stop' },
    { v: fmtPct(cusShare), u: '', l: 'Revenue share affected', c: cusShare > 0.3 ? 'crit' : cusShare > 0 ? 'warn' : 'ok', s: cus.site ? `${cus.site.label} ${cus.site.short_ja}: combined share of customers degraded or expected to stop (worst site)` : 'No customers degraded or expected to stop' },
    { v: fmt(single), u: '', l: 'Single-source partners affected', c: single ? 'crit' : 'ok', s: 'suppliers or logistics with no alternative under impact' },
    { v: fmt(lowInv), u: '', l: 'Inventory under 3 days', c: lowInv ? 'crit' : 'ok', s: 'drawn down from impact onset (assumed)' },
  ];
  const pts = rows.map((x) => [x.lon, x.lat]).concat((r.sites.length ? r.sites : siteIds.map((id) => regSites.find((s) => s.id === id)).filter(Boolean)).map((s) => [s.lon, s.lat]));
  const bb0 = sc.bbox || [pts[0][0], pts[0][1], pts[0][0], pts[0][1]]; const bbox = pts.reduce((b, p) => [Math.min(b[0], p[0]), Math.min(b[1], p[1]), Math.max(b[2], p[0]), Math.max(b[3], p[1])], bb0.slice()); const pad = 0.08; const bboxP = [bbox[0] - pad, bbox[1] - pad, bbox[2] + pad, bbox[3] + pad];
  const staffRows = (!Ctx.isGov() && !watch) ? siteIds.flatMap((sid) => ((g.staff[sid] || {}).clusters || []).map((cl) => { const d = cl.district ? r.districts.find((x) => x.id === cl.district) : null; const shs = d ? r.shelters.filter((s) => s.district === d.id) : []; return Object.assign({}, cl, { siteId: sid, d, shs }); })) : [];
  box.innerHTML = `<div class="kpis">${kpis.map(kpiTile).join('')}</div>
    <div class="card"><div class="card-h"><h2>Site operations and safety</h2><span class="r"><span class="tag neutral">as of ${esc(fmtHours(t))}</span></span><span class="sub">Site links open the day-to-day preparedness assessment (screen 1).</span></div><div class="tbl-wrap"><table><thead><tr><th>Site</th><th>Status</th><th class="n">Safety confirmed</th><th>Support needed</th><th>Preparedness</th></tr></thead><tbody>${siteRows || '<tr><td colspan="5" class="empty">No sites registered</td></tr>'}</tbody></table></div></div>
    <div class="grid map"><div class="card flush"><div class="map-box tall"><svg id="scMap" role="img" aria-label="Sites and partners"></svg><div class="legend"><span class="t">Legend</span><span><i style="background:var(--sel);border-radius:50%"></i>Our sites</span><span><i style="background:var(--c1);border-radius:50%"></i>Suppliers (circle)</span><span><i style="background:var(--c1);clip-path:polygon(50% 0,100% 100%,0 100%)"></i>Customers (triangle)</span><span><i style="background:var(--c1)"></i>Logistics / utilities (square)</span><span><i style="background:var(--crit);border-radius:50%"></i>Color = impact in home district (red: expected to stop / amber: degraded / green: no impact)</span></div><div class="attr">Natural Earth · partners are fictional</div></div></div>
      <div class="card"><div class="card-h"><h2>Supply chain status</h2><span class="r">${asmTag('Partners are fictional')}</span><span class="sub">Operating outlook is judged from the impact level in each partner's district. Remaining inventory is drawn down from impact onset.</span></div><div class="tbl-wrap"><table class="sc-table"><thead><tr><th>Partner</th><th>Relation</th><th>Status</th><th class="n">Inventory</th><th>Alternative</th></tr></thead><tbody>${rows.map((x) => `<tr><td><b>${esc(x.name_ja)}</b><span class="sub">${esc(x.tier || '')}${x.single ? ' · <b style="color:var(--crit)">single source</b>' : ''}${x.district && x.d ? ' · ' + esc(x.d.name_ja.split(' (')[0]) : ''}</span></td><td><span class="tag neutral">${esc(kindJa[x.kind] || x.kind)}</span><span class="sub">${x.share != null ? `share ${fmtPct(x.share)}` : ''}</span></td><td><span class="tag ${x.st === 'none' ? (watch ? 'warn' : 'neutral') : x.st}">${esc(stJa[x.st])}</span>${x.onset != null && x.st !== 'none' ? `<span class="sub">impact from ${esc(fmtHours(x.onset))}</span>` : x.district == null ? '<span class="sub">Outside scenario area</span>' : ''}</td><td class="n">${x.inv != null ? `<b style="color:${x.inv < 3 && x.st !== 'none' ? 'var(--crit)' : 'inherit'}">${fmt(x.inv, 1)} days</b>` : '—'}</td><td style="font-size:12px;color:var(--fg2)">${esc(x.alt_ja || '—')}</td></tr>`).join('') || '<tr><td colspan="5" class="empty">No partners registered</td></tr>'}</tbody></table></div></div></div>
    ${staffRows.length ? `<div class="card"><div class="card-h"><h2>Home districts of ${Ctx.isGov() ? 'personnel' : 'staff'} and families</h2><span class="r">${asmTag('Residence data fictional')}</span><span class="sub">Impact level and shelter occupancy in each home district. Individual safety status lives in the safety-confirmation system (the demo shows site-level rates only).</span></div><div class="tbl-wrap"><table><thead><tr><th>Home district</th><th class="n">People</th><th class="n">With family</th><th>Housing</th><th>District impact</th><th>Shelters</th></tr></thead><tbody>${staffRows.map((x) => `<tr><td><b>${esc(x.name_ja)}</b><span class="sub">${esc(regSites.find((s) => s.id === x.siteId).label)} site</span></td><td class="n">${fmt(x.n)}</td><td class="n">${fmt(x.fam)}</td><td style="font-size:12px">${esc(x.home_ja || '')}</td><td>${x.d ? `<span class="tag ${sevCls(x.d.I) || 'neutral'}">${sevJa(x.d.I)}${sc.type === 'flood' && x.d.depth > 0 ? ` · ${x.d.depth} m` : ''}</span>` : '<span class="tag neutral">Outside scenario area</span>'}</td><td style="font-size:12px">${x.shs.map((s) => s.open ? `<span class="tag ${s.over > 0 ? 'crit' : 'ok'}">${esc(s.name_ja)} ${fmt(s.occ)}/${fmt(s.cap)}</span>` : `<span class="tag neutral">${esc(s.name_ja)} not yet open</span>`).join(' ') || '—'}</td></tr>`).join('')}</tbody></table></div></div>` : ''}`;
  /* Map */
  const agg = {}; r.districts.forEach((d) => { const a = agg[d.adm1] || (agg[d.adm1] = { pop: 0, wI: 0 }); a.pop += d.pop; a.wI += d.pop * d.I; });
  const proj = renderRegionMap($('#scMap', box), { bbox: bboxP, labels: true, level: (f) => { const a = agg[f.properties.id]; if (!a) return (sc.map_adm1 || []).includes(f.properties.id) ? 'b1' : ''; const I = a.pop ? a.wI / a.pop : 0; return I > 0.6 ? 'b5' : I > 0.4 ? 'b4' : I > 0.2 ? 'b3' : I > 0.05 ? 'b2' : 'b1'; }, tip: (f) => `<b>${esc(f.properties.n)}</b>`, sites: (r.sites.length ? r.sites : siteIds.map((id) => regSites.find((s) => s.id === id)).filter(Boolean).map((s) => Object.assign({}, s, { op: 'Operating normally', status: 'ok' }))).map((s) => ({ id: s.id, lon: s.lon, lat: s.lat, label: s.label, name: `${s.name_ja}: ${s.op}`, status: s.status })), onSite: (id) => { const s = r.sites.find((x) => x.id === id); toast(s ? `${s.name_ja}: ${s.op}` : id); } });
  $('#scMap', box).insertAdjacentHTML('beforeend', `<g class="g-bub">${rows.map((x) => { const [px, py] = proj([x.lon, x.lat]); const col = x.st === 'crit' ? 'var(--crit)' : x.st === 'warn' ? 'var(--warn)' : x.st === 'ok' ? 'var(--c3)' : 'var(--ok)'; const shape = x.kind === 'logistics' || x.kind === 'utility' ? `<rect x="${(px - 6).toFixed(1)}" y="${(py - 6).toFixed(1)}" width="12" height="12" rx="2" fill="${col}" stroke="var(--surface)"/>` : x.kind === 'customer' ? `<path d="M${px.toFixed(1)} ${(py - 8).toFixed(1)}l7 12h-14z" fill="${col}" stroke="var(--surface)"/>` : `<circle cx="${px.toFixed(1)}" cy="${py.toFixed(1)}" r="7" fill="${col}" stroke="var(--surface)"/>`; return `<g style="pointer-events:none">${shape}<text class="m-label s" x="${(px + 9).toFixed(1)}" y="${(py + 3).toFixed(1)}">${esc(x.name_ja.split(' (')[0])}</text></g>`; }).join('')}</g>`);
}

/* ---------- District-level live information (used by the personal dashboard): utilities, relief events, weather, contacts, hospitals, street map ---------- */
function localLive(sc, t, did, opts = {}) {
  const r = sim(sc, t); const d = r.districts.find((x) => x.id === did) || null; const c = M.country(sc.country); const watch = sc.status === 'watch';
  const logiNow = (sc.logistics || []).map((l) => ({ l, s: l.states.filter((s) => s.t <= t).slice(-1)[0] || l.states[0] }));
  const util = r.util.length ? r.util.map((u) => { const a = u.per[did] ? u.per[did].avail : u.avail; const cls = a >= 0.8 ? 'ok' : a >= 0.4 ? 'warn' : 'crit'; const etaD = (u.eta_ja && u.eta_ja[did]) || u.eta_default_ja || 'Restoration time unknown'; const eta = a >= 0.97 ? (t <= 0 ? 'Supply continuing' : 'Largely normal') : a >= 0.8 ? `Mostly available (${etaD})` : etaD; return `<div class="st ${cls}"><div class="h">${ic(u.icon || 'bolt')}${esc(u.name_ja)}</div><div class="pct">${fmtPct(a)}</div><div class="track"><i style="width:${(a * 100).toFixed(0)}%;background:var(--${cls})"></i></div><div class="eta">${esc(eta)}</div></div>`; }).join('') + (logiNow.length ? `<div class="st" style="grid-column:1/-1;flex-direction:row;flex-wrap:wrap;gap:6px 14px;align-items:center"><span class="eb dim">Transport & logistics</span>${logiNow.map((x) => `<span class="tag ${x.s.cls}">${esc(x.l.name_ja)}: ${esc(x.s.ja)}</span>`).join('')}</div>` : '') : `<div class="st ok" style="grid-column:1/-1"><div class="h">${ic('bolt')}Utilities</div><div class="eta" style="font-size:13px;color:var(--fg)">${watch ? 'Normal during the watch phase. No power or water outages reported' : 'No information for this district'}</div></div>`;
  /* Relief events (districts without entries get shelter openings and water distribution generated automatically) */
  let evs = (sc.events || []).filter((e) => !e.district || e.district === did || e.district === '*'); let synthesized = false;
  if (!evs.length && !watch) { synthesized = true; const shs = (sc.shelters || []).filter((s) => s.district === did); evs = shs.flatMap((s) => [{ t: s.open_h || 0, dur: 168, ja: `${s.name_ja} opened (shelter, capacity ${fmt(s.cap)})`, short_ja: 'Shelter', where_ja: s.name_ja, for: ['Everyone'], by: 'Local government (assumed)' }, { t: (s.open_h || 0) + 12, dur: 120, ja: 'Water and food distribution (assumed)', short_ja: 'Water', where_ja: s.name_ja, for: ['Everyone'], by: 'Local government / Red Crescent (assumed)' }]); }
  const upcoming = evs.filter((e) => e.t + (e.dur || 4) > t).sort((a, b) => a.t - b.t).slice(0, 6); const past = evs.filter((e) => e.t + (e.dur || 4) <= t).slice(-3);
  const events = `<div class="card"><div class="card-h"><h2>Relief events</h2><span class="r">${d ? `<span class="tag neutral">${esc(d.name_ja.split(' (')[0])}</span>` : ''}${synthesized ? '<span class="tag warn">No entries · generated from shelters</span>' : ''}</span><span class="sub">${watch ? 'Watch phase: no relief events (water, hot meals) yet.' : synthesized ? 'No events are registered for this district, so shelter openings and water distribution are inferred from the scenario shelters.' : 'Water, hot meals, mobile clinics, consular services. Times are relative to onset (demo).'}</span></div><div class="ev-list">${upcoming.map((e) => `<div class="ev"><span class="t">${esc(fmtHours(e.t))}<small>${e.t <= t ? 'Now' : 'Planned'}</small></span><div><b>${esc(e.ja)}</b><span>${esc(e.where_ja || '')}${e.detail ? (e.where_ja ? ' · ' : '') + esc(e.detail) : ''}</span><div class="meta">${(e.for || []).map((f) => `<span class="tag neutral">${esc(f)}</span>`).join('')}${e.by ? `<span class="tag acc">${esc(e.by)}</span>` : ''}</div></div></div>`).join('') || `<div class="empty">${watch ? 'No relief events (watch phase)' : 'No relief events scheduled'}</div>`}${past.map((e) => `<div class="ev past"><span class="t">${esc(fmtHours(e.t))}<small>Ended</small></span><div><b>${esc(e.ja)}</b><span>${esc(e.where_ja || '')}</span></div></div>`).join('')}</div></div>`;
  const w = sc.weather || {}; const hi = w.temp != null && w.rh != null ? heatIndex(w.temp, w.rh) : null;
  const weather = `<div class="card"><div class="card-h"><h2>Temperature and precautions</h2><span class="r">${w.src ? srcTag(w.src_name || 'Source', w.src) : asmTag('Demo value')}${srcTag('NOAA Heat Index', 'https://www.weather.gov/ama/heatindex', 'Apparent temperature uses the NOAA Heat Index (from air temperature and humidity); it is a different measure from WBGT')}</span></div><div class="weather"><div class="big">${w.temp != null ? w.temp : '—'}<small>°C</small><div style="font-size:12px;color:var(--fg2);font-family:var(--f-body);font-weight:400">${esc(w.desc_ja || '')}</div></div><ul>${hi != null ? `<li>Heat index (NOAA) <b>${hi.toFixed(0)}°C</b>: ${hi >= 54 ? 'Extreme danger. Stop outdoor activity' : hi >= 41 ? 'Danger. Stop outdoor work; high risk of heat illness' : hi >= 32 ? 'Extreme caution. Rest and hydrate every 30 minutes during outdoor work' : hi >= 27 ? 'Caution. Drink water regularly' : 'Normal'} (NOAA's four bands)</li>` : ''}<li>Humidity <b>${w.rh != null ? w.rh + '%' : '—'}</b> · precipitation <b>${esc(w.rain_ja || '—')}</b></li>${(w.advice_ja || []).map((a) => `<li>${esc(a)}</li>`).join('')}</ul></div></div>`;
  const contacts = `<div class="card"><div class="card-h"><h2>Contacts</h2><span class="r"><span class="tag warn">To verify</span></span><span class="sub">Numbers and addresses are copied from third-party data. On arrival, verify them on your embassy's official site and update this screen.</span></div>${(c.emergency_numbers || []).slice(0, 4).map((n) => `<div class="contact"><div><b>${esc(n.service_ja)}</b><span>${esc(n.note_ja || '')}</span></div><button class="num copy" data-copy="${esc(n.number)}">${esc(n.number)}</button></div>`).join('')}${(c.disaster_hotlines || []).slice(0, 2).map((n) => `<div class="contact"><div><b>${esc(n.agency)}</b><span>${esc(n.note_ja || '')}</span></div><button class="num copy" data-copy="${esc(n.number)}">${esc(n.number)}</button></div>`).join('')}${(c.japanese_missions || []).slice(0, 1).map((m) => `<div class="contact"><div><b>${esc(m.name_ja)}</b><span>${esc(m.address || '')}${m.url ? ` <a href="${esc(m.url)}" target="_blank" rel="noopener">Website</a>` : ''}</span></div>${m.phone ? `<button class="num copy" data-copy="${esc(m.phone)}">${esc(m.phone)}</button>` : ''}</div>`).join('')}</div>`;
  const hosp = (sc.hospitals || []).map((h) => Object.assign({}, h, { st: h.states.filter((s) => s.t <= t).slice(-1)[0] || h.states[0] }));
  const hospitals = hosp.length ? `<div class="card"><div class="card-h"><h2>Hospitals accepting patients</h2><span class="sub">Intake status of hospitals that serve foreigners (demo). For minor cases use pharmacies or telemedicine instead, so emergency rooms stay clear.</span></div><div class="tbl-wrap"><table><thead><tr><th>Hospital</th><th>Status</th><th>Notes</th></tr></thead><tbody>${hosp.map((h) => `<tr><td><b>${esc(h.name_ja)}</b><span class="sub">${esc(h.district_ja || '')}${h.jp ? ' · international desk' : ''}</span></td><td><span class="tag ${h.st.cls}">${esc(h.st.ja)}</span></td><td style="font-size:12.5px;color:var(--fg2)">${esc(h.st.note || '')}</td></tr>`).join('')}</tbody></table></div></div>` : '';
  const hz = sc.type === 'watch' ? 'flood' : sc.type;
  const health = `<div class="card"><div class="card-h"><h2>Health precautions (${esc(hz === 'flood' ? 'floods' : hz === 'quake' ? 'after an earthquake' : (HAZ[hz] ? HAZ[hz].short.toLowerCase() : hz))})</h2><span class="r">${srcTag('WHO', 'https://www.who.int/')}</span></div><div style="display:flex;flex-direction:column;gap:8px">${((D.guidance && D.guidance.health_after_disaster) || []).filter((h) => h.hazard === hz || h.hazard === 'all').slice(0, 6).map((h) => `<div class="note">${ic(/dengue|mosquito|malaria|tick|vector/i.test(h.risk_ja) ? 'bug' : /heat|hot|sun/i.test(h.risk_ja) ? 'sun' : 'heart')}<span><b>${esc(h.risk_ja)}:</b> ${esc(h.advice_ja)} ${h.source_url ? srcTag('Source', h.source_url) : ''}</span></div>`).join('') || '<div class="empty">—</div>'}</div></div>`;
  /* Street map */
  const area = opts.area || (sc.area_id ? M.area(sc.area_id) : null); const showMap = area && (!sc.area_district || sc.area_district === did || opts.area);
  const mapHtml = showMap ? `<div class="card flush"><div class="map-box" id="llMapBox"><svg id="llMapSvg" role="img" aria-label="District situation map"></svg><div class="legend"><span class="t">Legend</span>${opts.home ? '<span><i style="background:var(--accent);border-radius:50%"></i>Home</span>' : ''}<span><i style="background:var(--amber);border-radius:50%"></i>Relief event</span><span><i style="background:var(--surface);border:2px solid var(--ok)"></i>Shelter occupancy/capacity</span>${hz === 'flood' ? '<span><i style="background:var(--m-flood);opacity:.4"></i>Assumed flood zone (shown at current depth)</span>' : '<span><i style="background:var(--crit);opacity:.3"></i>Heavily affected zone</span>'}</div><div class="attr">Schematic · demo</div></div></div>` : `<div class="note">${ic('info')}<span>No street map is registered for this district. See the Live reporting map for the wider impact distribution.</span></div>`;
  const mountMap = (box) => { if (!showMap) return; const A = area._built || (area._built = buildArea(area)); const evPins = upcoming.filter((e) => e.lat && e.lon).map((e) => { const [x, y] = localXY(area, e.lon, e.lat); return { x, y, label: e.short_ja || e.ja }; }); const shelters = r.shelters.filter((s) => s.poi).map((s) => ({ poi: s.poi, occ: s.occ, cap: s.cap })); const depth = d ? d.depth : 0; renderAreaMap($('#llMapSvg', box), A, area, { scenario: hz === 'flood' ? (depth > 0.15 ? 'flood' : null) : 'quake', zoneCls: hz === 'flood' ? 'sm-flood' : 'sm-shake', events: evPins, shelters, me: opts.home || null, site: sc.area_site ? (() => { const s = M.site(sc.area_site); const [x, y] = localXY(area, s.lon, s.lat); return { x, y, name: s.label + ' site' }; })() : null, onPoi: (n) => toast(n) }); };
  return { r, d, util, events, weather, contacts, hospitals, health, mapHtml, mountMap, upcoming, watch };
}
/* Heat index (NOAA Heat Index, °C) */
function heatIndex(tc, rh) { const T = tc * 9 / 5 + 32; const simple = 0.5 * (T + 61 + (T - 68) * 1.2 + rh * 0.094); if ((simple + T) / 2 < 80) return (simple - 32) * 5 / 9; const HI = -42.379 + 2.04901523 * T + 10.14333127 * rh - 0.22475541 * T * rh - 6.83783e-3 * T * T - 5.481717e-2 * rh * rh + 1.22874e-3 * T * T * rh + 8.5282e-4 * T * rh * rh - 1.99e-6 * T * T * rh * rh; return (HI - 32) * 5 / 9; }
